import{_ as s,a0 as a,w as p,s as d,I as l,x as i,a1 as o,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何創建適合移動設備的文檔 | LCTT x X-CMD","titleTemplate":false,"description":"如何創建適合移動設備的文檔 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何創建適合移動設備的文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何創建適合移動設備的文檔 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171221 How to create mobile-friendly documentation","title":"如何創建適合移動設備的文檔","tag":"201805","desc":""},"relativePath":"201805/20171221 How to create mobile-friendly documentation.md","filePath":"[post].md"}'),u={name:"201805/20171221 How to create mobile-friendly documentation.md"};function m(f,t,T,b,g,k){const e=a("Link");return p(),d("div",null,[t[30]||(t[30]=l("h1",{id:"如何創建適合移動設備的文檔",tabindex:"-1"},[i("如何創建適合移動設備的文檔 "),l("a",{class:"header-anchor",href:"#如何創建適合移動設備的文檔","aria-label":"Permalink to “如何創建適合移動設備的文檔”"},"​")],-1)),t[31]||(t[31]=l("blockquote",null,[l("p",null,"幫助用户在智能手機或平板上快速輕鬆地找到他們所需的信息。")],-1)),t[32]||(t[32]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/idea_innovation_mobile_phone.png?itok=RqVtvxkd",alt:"配圖"})],-1)),l("p",null,[t[1]||(t[1]=i("我並不是完全相信",-1)),o(e,{href:"https://www.uxmatters.com/mt/archives/2012/03/mobile-first-what-does-it-mean.php"},{default:n(()=>[...t[0]||(t[0]=[i("移動為先",-1)])]),_:1}),t[2]||(t[2]=i("的理念，但是我確實發現更多的人使用智能手機和平板電腦等移動設備來獲取信息。這包括在線的軟件和硬件文檔，但它們大部分都是冗長的，不適合小屏幕。通常情況下，它的伸縮性不太好，而且很難導航。",-1))]),t[33]||(t[33]=r('<p>當用户使用移動設備訪問文檔時，他們通常需要迅速獲取信息以瞭解如何執行任務或解決問題，他們不想通過看似無盡的頁面來尋找他們需要的特定信息。幸運的是，解決這個問題並不難。以下是一些技巧，可以幫助你構建文檔以滿足移動閲讀器的需求。</p><h3 id="簡短一點" tabindex="-1">簡短一點 <a class="header-anchor" href="#簡短一點" aria-label="Permalink to “簡短一點”">​</a></h3><p>這意味着簡短的句子，簡短的段落和簡短的流程。你不是在寫一部長篇小説或一段長新聞。使你的文檔簡潔。儘可能使用少量的語言來獲得想法和信息。</p><p>以廣播新聞報道為示範：關注關鍵要素，用簡單直接的語言對其進行解釋。不要讓你的讀者在屏幕上看到冗長的文字。</p><p>另外，直接切入重點。關注讀者需要的信息。在線發佈的文檔不應該像以前厚厚的手冊一樣。不要把所有東西都放在一個頁面上，把你的信息分成更小的塊。接下來是怎樣做到這一點：</p><h3 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to “主題”">​</a></h3><p>在技術寫作的世界裏，主題是獨立的，獨立的信息塊。每個主題都由你網站上的單個頁面組成。讀者應該能從特定的主題中獲取他們需要的信息 -- 並且只是那些信息。要做到這一點，選擇哪些主題要包含在文檔中並決定如何組織它們：</p><h3 id="dita" tabindex="-1">DITA <a class="header-anchor" href="#dita" aria-label="Permalink to “DITA”">​</a></h3>',8)),l("p",null,[l("ruby",null,[o(e,{href:"https://en.wikipedia.org/wiki/Darwin_Information_Typing_Architecture"},{default:n(()=>[...t[3]||(t[3]=[i("達爾文信息類型化體系結構",-1)])]),_:1}),t[4]||(t[4]=l("rt",null,"Darwin Information Typing Architecture",-1))]),t[6]||(t[6]=i(" （DITA） 是用於編寫和發佈的一個 XML 模型。它",-1)),o(e,{href:"http://dita.xml.org/book/list-of-organizations-using-dita"},{default:n(()=>[...t[5]||(t[5]=[i("廣泛採用",-1)])]),_:1}),t[7]||(t[7]=i("在技術寫作中，特別是作為較長的文檔集中。",-1))]),t[34]||(t[34]=r('<p>我並不是建議你將文檔轉換為 XML（除非你真的想）。相反，考慮將 DITA 的不同類型主題的概念應用到你的文檔中：</p><ul><li>一般：概述信息</li><li>任務：分步驟的流程</li><li>概念：背景或概念信息</li><li>參考：API 參考或數據字典等專用信息</li><li>術語表：定義術語</li><li>故障排除：有關用户可能遇到的問題以及如何解決問題的信息</li></ul><p>你會得到很多單獨的頁面。要連接這些頁面：</p><h3 id="鏈接" tabindex="-1">鏈接 <a class="header-anchor" href="#鏈接" aria-label="Permalink to “鏈接”">​</a></h3>',4)),l("p",null,[t[9]||(t[9]=i("許多內容管理系統、維基和發佈框架都包含某種形式的導航 —— 通常是目錄或",-1)),o(e,{href:"https://en.wikipedia.org/wiki/Breadcrumb_(navigation)"},{default:n(()=>[...t[8]||(t[8]=[i("麪包屑導航",-1)])]),_:1}),t[10]||(t[10]=i("，這是一種在移動設備上逐漸消失的導航。",-1))]),t[35]||(t[35]=r('<p>為了加強導航，在主題之間添加明確的鏈接。將這些鏈接放在每個主題末尾的標題<strong>另請參閲</strong>或<strong>相關主題</strong>。每個部分應包含兩到五個鏈接，指向與當前主題相關的概述、概念和參考主題。</p><p>如果你需要指向文檔集之外的信息，請確保鏈接在瀏覽器新的選項卡中打開。這將把讀者送到另一個網站，同時也將讀者繼續留你的網站上。</p><p>這解決了文本問題，那麼圖片呢？</p><h3 id="不使用圖片" tabindex="-1">不使用圖片 <a class="header-anchor" href="#不使用圖片" aria-label="Permalink to “不使用圖片”">​</a></h3><p>除少數情況之外，不應該加太多圖片到文檔中。仔細查看文檔中的每個圖片，然後問自己：</p><ul><li>它有用嗎？</li><li>它是否增強了文檔？</li><li>如果刪除它，讀者會錯過這張圖片嗎？</li></ul><p>如果回答否，那麼移除圖片。</p>',7)),l("p",null,[t[12]||(t[12]=i("另一方面，如果你絕對不能沒有圖片，就讓它變成",-1)),o(e,{href:"https://en.wikipedia.org/wiki/Responsive_web_design"},{default:n(()=>[...t[11]||(t[11]=[i("響應式的",-1)])]),_:1}),t[13]||(t[13]=i("。這樣，圖片就會自動調整以適應更小的屏幕。",-1))]),l("p",null,[t[15]||(t[15]=i("如果你仍然不確定圖片是否應該出現，Opensource.com 社區版主 Ben Cotton 提供了一個關於在文檔中使用屏幕截圖的",-1)),o(e,{href:"https://opensource.com/business/15/9/when-does-your-documentation-need-screenshots"},{default:n(()=>[...t[14]||(t[14]=[i("極好的解釋",-1)])]),_:1}),t[16]||(t[16]=i("。",-1))]),t[36]||(t[36]=l("h3",{id:"最後的想法",tabindex:"-1"},[i("最後的想法 "),l("a",{class:"header-anchor",href:"#最後的想法","aria-label":"Permalink to “最後的想法”"},"​")],-1)),t[37]||(t[37]=l("p",null,"通過少量努力，你就可以構建適合移動設備用户的文檔。此外，這些更改也改進了桌面計算機和筆記本電腦用户的文檔體驗。",-1)),t[38]||(t[38]=l("hr",null,null,-1)),l("p",null,[t[18]||(t[18]=i("via: ",-1)),o(e,{href:"https://opensource.com/article/17/12/think-mobile"},{default:n(()=>[...t[17]||(t[17]=[i("https://opensource.com/article/17/12/think-mobile",-1)])]),_:1})]),l("p",null,[t[22]||(t[22]=i("作者：",-1)),o(e,{href:"https://opensource.com/users/chrisshort"},{default:n(()=>[...t[19]||(t[19]=[i("Scott Nesbitt",-1)])]),_:1}),t[23]||(t[23]=i(" 譯者：",-1)),o(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...t[20]||(t[20]=[i("MjSeven",-1)])]),_:1}),t[24]||(t[24]=i(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[27]||(t[27]=i("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[25]||(t[25]=[i("LCTT",-1)])]),_:1}),t[28]||(t[28]=i(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:n(()=>[...t[26]||(t[26]=[i("Linux中國",-1)])]),_:1}),t[29]||(t[29]=i(" 榮譽推出",-1))])])}const A=s(u,[["render",m]]);export{C as __pageData,A as default};
